var all=document.getElementById('showAllPhotos');if(all)all.addEventListener('click',function(){open(0)});if(galleryRoot&&mobileCounter){function updateMobileCounter(){var tiles=galleryRoot.querySelectorAll('.gallery-tile');if(!tiles.length)return;var nearest=0,distance=Infinity;tiles.forEach(function(tile,i){var d=Math.abs(tile.offsetLeft-galleryRoot.scrollLeft);if(d<distance){distance=d;nearest=i}});mobileCounter.textContent=(nearest+1)+' / '+galleryImages.length}galleryRoot.addEventListener('scroll',function(){window.requestAnimationFrame(updateMobileCounter)},{passive:true});window.addEventListener('resize',updateMobileCounter);updateMobileCounter()}
document.getElementById('lightboxClose').addEventListener('click',close);document.getElementById('lightboxPrev').addEventListener('click',function(){show(index-1)});document.getElementById('lightboxNext').addEventListener('click',function(){show(index+1)});
modal.addEventListener('click',function(e){if(e.target===modal)close()});document.addEventListener('keydown',function(e){if(!modal.classList.contains('is-open'))return;if(e.key==='Escape')close();if(e.key==='ArrowLeft')show(index-1);if(e.key==='ArrowRight')show(index+1)});
modal.addEventListener('touchstart',function(e){touchX=e.changedTouches[0].screenX},{passive:true});modal.addEventListener('touchend',function(e){var delta=e.changedTouches[0].screenX-touchX;if(Math.abs(delta)>45)show(index+(delta<0?1:-1))},{passive:true});
})();

(function(){var root=document.getElementById('villaAvailability');if(!root)return;var grid=document.getElementById('villaCalendarGrid'),monthLabel=document.getElementById('calendarMonth'),status=document.getElementById('villaCalendarStatus'),selection=document.getElementById('calendarSelectionText'),reserve=document.getElementById('calendarReserve');var checkIn=document.getElementById('bookingCheckIn'),checkOut=document.getElementById('bookingCheckOut'),guestSelect=document.getElementById('bookingGuests');var now=new Date(),view=new Date(now.getFullYear(),now.getMonth(),1),today=new Date(now.getFullYear(),now.getMonth(),now.getDate()),first=checkIn&&checkIn.value?checkIn.value:null,last=checkOut&&checkOut.value?checkOut.value:null,bookings=[],rules=[];var names=['Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık'];if(first){var initialDate=new Date(first+'T00:00:00');if(!isNaN(initialDate.getTime()))view=new Date(initialDate.getFullYear(),initialDate.getMonth(),1)}function iso(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}function parse(s){var p=s.split('-').map(Number);return new Date(p[0],p[1]-1,p[2])}function dayState(d){var key=iso(d);for(var b of bookings)if(key>=b.check_in&&key<b.check_out)return b.status==='confirmed'?'booked':'pending';for(var r of rules)if(key>=r.date_from&&key<r.date_to&&r.status!=='available')return 'blocked';return 'available'}function blocked(d){return d<today||['booked','pending','blocked'].includes(dayState(d))}function render(){grid.innerHTML='';['Pzt','Sal','Çar','Per','Cum','Cmt','Paz'].forEach(function(n){var el=document.createElement('div');el.className='calendar-weekday';el.textContent=n;grid.appendChild(el)});var offset=(view.getDay()+6)%7;for(var i=0;i<offset;i++){var empty=document.createElement('div');empty.className='calendar-day empty';grid.appendChild(empty)}var count=new Date(view.getFullYear(),view.getMonth()+1,0).getDate();for(var n=1;n<=count;n++){var d=new Date(view.getFullYear(),view.getMonth(),n),state=dayState(d),key=iso(d),el=document.createElement('button');el.type='button';el.className='calendar-day '+state+(d<today?' past':'');var inRange=first&&last&&key>=first&&key<=last;if(key===first||key===last)el.classList.add('selected');else if(inRange)el.classList.add('in-range');el.disabled=blocked(d);var label=state==='booked'?'Dolu':state==='pending'?'Talep':state==='blocked'?'Kapalı':'Müsait';el.innerHTML='<span class="day-number">'+n+'</span><span class="day-state">'+label+'</span>';el.addEventListener('click',(function(date){return function(){choose(iso(date))}})(d));grid.appendChild(el)}monthLabel.textContent=names[view.getMonth()]+' '+view.getFullYear()}function choose(key){if(!first||last||key<=first){first=key;last=null}else{last=key}if(checkIn)checkIn.value=first||'';if(checkOut)checkOut.value=last||'';if(first&&last){var start=parse(first),end=parse(last),bad=false;for(var d=new Date(start);d<end;d.setDate(d.getDate()+1)){if(blocked(d)){bad=true;break}}if(bad){last=null;status.textContent='Seçtiğiniz aralıkta dolu veya kapalı gün bulunuyor. Başka bir çıkış tarihi seçin.'}else{status.textContent='Fiyat ve müsaitlik doğrulanıyor…';var u=new URL(root.dataset.priceUrl,location.origin);u.searchParams.set('check_in',first);u.searchParams.set('check_out',last);u.searchParams.set('guests',guestSelect?guestSelect.value:'1');fetch(u,{headers:{Accept:'application/json'}}).then(r=>r.json()).then(data=>{if(data.ok){status.textContent=data.nights+' gece · Toplam '+new Intl.NumberFormat('tr-TR',{style:'currency',currency:data.currency}).format(data.total)+' · Müsait';reserve.href=root.dataset.reserveUrl+'?'+new URLSearchParams({check_in:first,check_out:last,guests:guestSelect?guestSelect.value:'1'}).toString();reserve.setAttribute('aria-disabled','false')}else{last=null;status.textContent=data.message||'Bu tarih aralığı müsait değil.';reserve.href='#';reserve.setAttribute('aria-disabled','true')}renderSelection();render()}).catch(()=>{status.textContent='Müsaitlik doğrulanamadı. Lütfen tekrar deneyin.';last=null;renderSelection();render()})}}else{status.textContent='Şimdi çıkış tarihinizi seçin.';reserve.href='#';reserve.setAttribute('aria-disabled','true')}renderSelection();render()}function renderSelection(){selection.textContent=first?(last?'Giriş: '+first+' · Çıkış: '+last:'Giriş: '+first+' · Çıkış tarihini seçin'):'Giriş ve çıkış tarihlerinizi takvimden seçin.'}function load(){var m=view.getFullYear()+'-'+String(view.getMonth()+1).padStart(2,'0');status.textContent='Müsaitlik bilgisi yükleniyor…';fetch(root.dataset.calendarUrl+'?month='+m,{headers:{Accept:'application/json'}}).then(r=>r.json()).then(data=>{if(!data.ok)throw new Error(data.message||'Takvim yüklenemedi');bookings=data.bookings||[];rules=data.rules||[];status.textContent='Takvim güncel rezervasyon ve kapalı gün kayıtlarına göre gösteriliyor.';render()}).catch(()=>{status.textContent='Takvim bilgisi alınamadı. Lütfen sayfayı yenileyin.';grid.innerHTML='';render()})}document.getElementById('calendarPrev').addEventListener('click',function(){view.setMonth(view.getMonth()-1);load()});document.getElementById('calendarNext').addEventListener('click',function(){view.setMonth(view.getMonth()+1);load()});if(checkIn)checkIn.addEventListener('change',function(){first=checkIn.value||null;last=null;if(checkOut)checkOut.value='';renderSelection();render()});if(checkOut)checkOut.addEventListener('change',function(){if(checkIn&&checkIn.value&&checkOut.value&&checkOut.value>checkIn.value){first=checkIn.value;last=checkOut.value;var u=new URL(root.dataset.priceUrl,location.origin);u.searchParams.set('check_in',first);u.searchParams.set('check_out',last);u.searchParams.set('guests',guestSelect?guestSelect.value:'1');fetch(u,{headers:{Accept:'application/json'}}).then(r=>r.json()).then(data=>{if(data.ok){status.textContent=data.nights+' gece · Toplam '+new Intl.NumberFormat('tr-TR',{style:'currency',currency:data.currency}).format(data.total)+' · Müsait';reserve.href=root.dataset.reserveUrl+'?'+new URLSearchParams({check_in:first,check_out:last,guests:guestSelect?guestSelect.value:'1'}).toString();reserve.setAttribute('aria-disabled','false')}else{last=null;checkOut.value='';status.textContent=data.message||'Bu tarih aralığı müsait değil.';reserve.href='#';reserve.setAttribute('aria-disabled','true')}renderSelection();render()}).catch(function(){status.textContent='Müsaitlik doğrulanamadı.'})}else{last=null;reserve.href='#';reserve.setAttribute('aria-disabled','true')}renderSelection();render()});if(guestSelect)guestSelect.addEventListener('change',function(){if(first&&last&&checkOut)checkOut.dispatchEvent(new Event('change'))});load()})();
</script><script>(function(){document.querySelectorAll('.js-favorite-form').forEach(function(form){form.addEventListener('submit',async function(event){event.preventDefault();var button=form.querySelector('button[type="submit"]');if(!button||button.disabled)return;var oldText=button.textContent;button.disabled=true;try{var response=await fetch(form.action,{method:'POST',body:new FormData(form),credentials:'same-origin',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}});var data=await response.json();if(!response.ok||!data.ok)throw new Error(data.message||'Favori işlemi tamamlanamadı.');button.classList.toggle('is-active',!!data.active);button.setAttribute('aria-pressed',data.active?'true':'false');button.textContent=data.active?'♥ Favorilerden çıkar':'♡ Favorilere ekle';var status=document.getElementById('favoriteActionStatus');if(!status){status=document.createElement('div');status.id='favoriteActionStatus';status.setAttribute('role','status');status.setAttribute('aria-live','polite');status.style.cssText='position:fixed;left:50%;bottom:22px;transform:translateX(-50%);z-index:6000;padding:11px 16px;border-radius:999px;background:#20352e;color:var(--villa-text);font:inherit;box-shadow:0 8px 24px #0002';document.body.appendChild(status)}status.textContent=data.message;status.hidden=false;clearTimeout(status._hideTimer);status._hideTimer=setTimeout(function(){status.hidden=true},2400)}catch(error){button.textContent=oldText;window.alert(error.message||'Favori işlemi sırasında hata oluştu.')}finally{button.disabled=false}})})})();</script><?php \App\Core\ThemeManager::renderPartial('partials/login-modal.php', get_defined_vars()); ?><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>(function(){var el=document.getElementById("propertyLocationMap");if(!el||!window.L)return;var lat=Number(el.dataset.lat),lng=Number(el.dataset.lng);if(!Number.isFinite(lat)||!Number.isFinite(lng))return;var map=L.map(el,{scrollWheelZoom:false}).setView([lat,lng],14);L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:19,attribution:"&copy; OpenStreetMap"}).addTo(map);L.marker([lat,lng]).addTo(map);setTimeout(function(){map.invalidateSize()},150)})();</script></body></html>